window.FOUNDATION=[{"remember": "兒童線上數學思考課程；真人老師帶領；觀察、嘗試與表達。", "explain": "用一個具體行為說明孩子在練習什麼。", "check": "個別效果、進步時間；是否對應特定校內單元。"}, {"remember": "幼兒從熟悉情境練習觀察、比較與表達；國小進一步整理條件與運用方法；九階循序安排，也關注思考、習慣與情感。", "explain": "用例子說明幼兒與國小的培養方向，分清內容與教學安排。", "check": "個別適合階段、各階體驗課的具體內容與推薦。"}, {"remember": "S1：4–6 人／30–35 分鐘；S2：4–6 人／40–45 分鐘；S3–S9：6–8 人／40–45 分鐘；每週 2 次。", "explain": "一般上課與受邀上小舞臺的差別。", "check": "當次班級安排與教材未提供的具體操作規則。"}, {"remember": "真人小班直播；體驗人數依階段、時段與當天報名確認；中文＋繁體課件，英文＋英文課件；手機、平板、筆電皆可。", "explain": "哪些基本安排已知，哪些要確認當次情況。", "check": "當次人數、適合階段、帳號與登入方式、實際時段。"}, {"remember": "資源按用途區分；體驗練習 3 個環節、每環節 2 題，約 6 題；體驗課回放 180 天；三師各有分工。", "explain": "依需求選資源，說清回放期限適用範圍。", "check": "其他資源期限、具體師資身分、個別學習判斷。"}, {"remember": "4 堂以內包含第 4 堂可申請全額退費；超過 4 堂依公式；7–14 個工作日，原付款方式。", "explain": "先判斷堂數界線，再說明公式、時間與方式。", "check": "訂單金額、基礎直播課堂數、剩餘堂數、個案辦理進度；不保證進步時間。"}];
